import numpy as np


def importance_weights(current_logprobs, behavior_logprobs, max_log_ratio=None):
    current = np.asarray(current_logprobs, dtype=float)
    behavior = np.asarray(behavior_logprobs, dtype=float)
    if current.ndim != 1 or current.shape != behavior.shape or current.size == 0:
        raise ValueError("inputs must be non-empty 1-D arrays of equal shape")
    if not np.isfinite(current).all() or not np.isfinite(behavior).all():
        raise ValueError("log probabilities must be finite")
    if np.any(current > 0) or np.any(behavior > 0):
        raise ValueError("log probabilities must be non-positive")

    log_ratio = current - behavior
    if max_log_ratio is not None:
        if not np.isfinite(max_log_ratio):
            raise ValueError("max_log_ratio must be finite")
        log_ratio = np.minimum(log_ratio, max_log_ratio)
    return np.exp(log_ratio)


def effective_sample_size(weights, normalized=False):
    w = np.asarray(weights, dtype=float)
    if w.ndim != 1 or w.size == 0 or not np.isfinite(w).all():
        raise ValueError("weights must be a finite non-empty vector")
    if np.any(w < 0):
        raise ValueError("weights must be non-negative")
    denom = float(np.dot(w, w))
    if denom == 0:
        raise ValueError("at least one weight must be positive")
    ess = float(w.sum() ** 2 / denom)
    return ess / w.size if normalized else ess
```

```python
import math

REQUIRED = {
    "sample_id", "prompt_id", "policy_version",
    "prompt_tokens", "response_tokens", "behavior_logprobs",
    "decoding", "reward", "stop_reason", "verifier_version",
}


def rollout_contract_errors(record):
    if not isinstance(record, dict):
        return ["record must be a dict"]

    errors = []
    missing = sorted(REQUIRED - set(record))
    if missing:
        errors.append("missing fields: " + ", ".join(missing))

    version = record.get("policy_version")
    if isinstance(version, bool) or not isinstance(version, int) or version < 0:
        errors.append("policy_version must be a non-negative integer")

    for key in ("prompt_tokens", "response_tokens"):
        tokens = record.get(key)
        if not isinstance(tokens, list) or any(
            isinstance(token, bool) or not isinstance(token, int) or token < 0
            for token in (tokens or [])
        ):
            errors.append(f"invalid {key}")

    logps = record.get("behavior_logprobs")
    if not isinstance(logps, list) or any(
        not isinstance(value, (int, float))
        or not math.isfinite(value)
        or value > 0
        for value in (logps or [])
    ):
        errors.append("invalid behavior_logprobs")
    elif isinstance(record.get("response_tokens"), list) and len(logps) != len(record["response_tokens"]):
        errors.append("logprobs do not align with response_tokens")

    return errors
```

Полная эталонная версия дополнительно проверяет строки, вложенные отображения и выдаёт более точные сообщения.
В М11 `token_ids`, `policy_mask` и `turn_ids` описывают всю траекторию, а `policy_versions` — версии её ходов. Здесь выберите одно продолжение, созданное одной поведенческой версией: `prompt_tokens` — контекст перед его генерацией, `response_tokens` — выбранные политикой токены этого продолжения, `behavior_logprobs` выровнены именно с ними. Одиночная числовая `policy_version` требует явного реестра версий; строку версии нельзя молча приводить к числу. `prompt_id` задаётся при формировании запроса. Преобразование `rewards` в `reward` и выбор `stop_reason` требуют объявленного правила кредитования и остановки данного продолжения; итог эпизода не следует автоматически приписывать каждому ходу. Идентификаторы среды, действия, наблюдения, происхождение токенов и флаги всей траектории остаются в исходном журнале, связанном с инфраструктурной записью. Это проекция на другую единицу данных, а не замена полного агентного контракта.

